DROP ROLE IF EXISTS altareeq_test_app;CREATE ROLE altareeq_test_app NOLOGIN;GRANT USAGE ON SCHEMA public TO altareeq_test_app;GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO altareeq_test_app;GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO altareeq_test_app;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO altareeq_test_app;
