DO $$ BEGIN IF(SELECT sum(debit_minor)=sum(credit_minor) FROM journal_lines WHERE journal_id='40000000-0000-4000-8000-000000000001') IS NOT TRUE THEN RAISE EXCEPTION 'balance invariant';END IF;END $$;
