DO $$ BEGIN BEGIN UPDATE journals SET description='tamper' WHERE id='40000000-0000-4000-8000-000000000001';RAISE EXCEPTION 'immutable trigger failed';EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM<>'POSTED_JOURNAL_IMMUTABLE' THEN RAISE;END IF;END;END $$;
